class Solution {
public:
    string repeatLimitedString(string s, int repeatLimit) {
        int count[26] = {0};
        for (char c : s) count[c - 'a']++;
        string result;
        result.reserve(s.size());
        int i = 25;
        while (i >= 0) {
            if (count[i] == 0) {
                i--;
                continue;
            }
            int take = min(repeatLimit, count[i]);
            result.append(take, 'a' + i);
            count[i] -= take;
            if (count[i] > 0) {
                int j = i - 1;
                while (j >= 0 && count[j] == 0) j--;
                if (j < 0) break;
                result.append(1, 'a' + j);
                count[j]--;
            }
        }
        return result;
    }
};
